import requests

def test_get_apidebugtables_returns_database_tables_and_row_counts():
    base_url = "http://localhost:5001"
    endpoint = "/api/debug/tables"
    url = base_url + endpoint
    headers = {
        "Accept": "application/json"
    }
    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert isinstance(data, dict), f"Response JSON is not a dict, got {type(data).__name__}"

    # Check that each key is a string and each value is an int, str or dict
    for table_name, value in data.items():
        assert isinstance(table_name, str), f"Table name is not a string: {table_name}"
        # Accept int (row count), str (like db_host), or dict (like 'tables')
        if not isinstance(value, (int, str, dict)):
            assert False, f"Value for '{table_name}' has unexpected type: {type(value).__name__}"

test_get_apidebugtables_returns_database_tables_and_row_counts()

import requests

BASE_URL = "http://localhost:5001"
TIMEOUT = 30

def test_post_apisyncuser_upserts_user_record():
    url = f"{BASE_URL}/api/sync-user"
    headers = {
        "Content-Type": "application/json"
    }

    # Valid payload with email, name, image
    valid_payload = {
        "email": "testuser@example.com",
        "name": "Test User",
        "image": "https://example.com/avatar.png"
    }

    response = requests.post(url, json=valid_payload, headers=headers, timeout=TIMEOUT)
    try:
        # Assert status code 200
        assert response.status_code == 200, f"Expected 200, got {response.status_code}"

        # Assert response JSON contains at least 'id' and 'email' matching payload email
        json_resp = response.json()
        assert "id" in json_resp, "Response JSON missing 'id'"
        assert "email" in json_resp, "Response JSON missing 'email'"
        assert json_resp["email"] == valid_payload["email"], "Response email does not match request email"
    finally:
        # Clean up: delete user if possible (assuming DELETE /api/sync-user/{id} exists)
        user_id = None
        try:
            user_id = response.json().get("id")
        except Exception:
            pass
        if user_id:
            try:
                requests.delete(f"{url}/{user_id}", timeout=TIMEOUT)
            except Exception:
                pass

    # Valid payload with email only (google_id optional)
    email_only_payload = {
        "email": "emailonlyuser@example.com"
    }

    response_email_only = requests.post(url, json=email_only_payload, headers=headers, timeout=TIMEOUT)
    try:
        assert response_email_only.status_code == 200, f"Expected 200, got {response_email_only.status_code}"
        json_resp = response_email_only.json()
        assert "id" in json_resp, "Response JSON missing 'id'"
        assert "email" in json_resp, "Response JSON missing 'email'"
        assert json_resp["email"] == email_only_payload["email"], "Response email does not match request email"
    finally:
        user_id = None
        try:
            user_id = response_email_only.json().get("id")
        except Exception:
            pass
        if user_id:
            try:
                requests.delete(f"{url}/{user_id}", timeout=TIMEOUT)
            except Exception:
                pass

    # Invalid payload missing email -> should return 400 validation error
    invalid_payload = {
        "name": "No Email User",
        "image": "https://example.com/avatar.png"
    }

    response_invalid = requests.post(url, json=invalid_payload, headers=headers, timeout=TIMEOUT)
    assert response_invalid.status_code == 400, f"Expected 400, got {response_invalid.status_code}"

test_post_apisyncuser_upserts_user_record()

