import requests

BASE_URL = "http://localhost:5001"
TIMEOUT = 30

# Example bearer token for auth - replace with valid token
AUTH_TOKEN = "Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.fake_token_for_testing"

def test_post_apistripecreatecheckout_creates_stripe_checkout_session():
    url = f"{BASE_URL}/api/stripe/create-checkout"
    headers = {
        "Authorization": AUTH_TOKEN,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    # Payload is assumed empty or minimal if not specified. Typically Stripe checkout requires line items etc.
    # Since PRD does not specify request body schema for this endpoint, send empty JSON object.
    payload = {}

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    if response.status_code == 200:
        # Expect JSON body with a checkout url string field
        try:
            data = response.json()
        except ValueError:
            assert False, "Response is not valid JSON."

        assert isinstance(data, dict), "Response JSON is not an object."
        assert "url" in data, "Response JSON does not contain 'url' field."
        assert isinstance(data["url"], str) and (data["url"].startswith("http") or data["url"].startswith("/")), f"Invalid checkout url: {data['url']}"

    elif response.status_code == 500:
        # Stripe service errors return 500, the body may contain error details
        try:
            data = response.json()
            # Optional: check error message presence
            assert "error" in data or "message" in data or True
        except ValueError:
            # Accept even if not JSON error details
            pass

    else:
        assert False, f"Unexpected status code {response.status_code} from {url}, expected 200 or 500."


test_post_apistripecreatecheckout_creates_stripe_checkout_session()
